// ✏️  FILL IN THE VALUES BELOW, then click Save.
// Every other node in this workflow reads its settings from here.
return [{
  json: {
    // ZIP codes you serve, separated by commas, e.g. "94103, 94107, 94110". Leave empty to accept every ZIP.
    service_zip_codes: "",
  },
}];

const req = $('Vapi Tool Call').first().json;
const body = req.body ?? req;
const msg = body.message ?? body;
const call = msg.call ?? body.call ?? {};
const toolCall =
  (msg.toolCallList ?? msg.toolCalls ?? [])[0] ??
  msg.toolWithToolCallList?.[0]?.toolCall ?? {};
// Function tools send Vapi's tool-call envelope; API Request tools POST the
// parameters as the whole body.
let args = toolCall.function?.arguments ?? toolCall.arguments ?? (body.message ? {} : body);
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { args = {}; }
}
const toolCallId = toolCall.id ?? '';

const cfg = $('Config').first().json;
const zip = String(args.zip_code ?? '').match(/\d{5}/)?.[0] ?? '';
const served = String(cfg.service_zip_codes ?? '').match(/\d{5}/g) ?? [];

let result;
if (!zip) {
  result = "No valid 5-digit ZIP code was given. Ask the caller to repeat their ZIP code.";
} else if (served.length === 0 || served.includes(zip)) {
  result = `IN AREA: ZIP ${zip} is inside the service area. Continue the intake.`;
} else {
  result = `OUT OF AREA: ZIP ${zip} is outside the service area. Follow the out-of-area script.`;
}
return [{ json: { tool_call_id: toolCallId, result } }];
